-- G検定 Set E (g-kentei-e) 50問 seed。フルclarity＋仕組み系に因果の背骨。
BEGIN;

INSERT INTO public.subjects (slug, name, description, color, sort_order, is_active)
VALUES ('g-kentei-e', 'G検定（JDLA ジェネラリスト検定） Set E',
        'JDLA G検定 対策 第5弾。シラバス2024準拠。本試験はオンライン100分/小問145問程度・多肢選択式。個人情報保護法は範囲外（保有資格のため意図的に除外）。本番の再現ではなく学習用オリジナル。',
        '#0B5CAB', 54, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, v.name, v.color, v.sort_order
FROM public.subjects s
CROSS JOIN (VALUES
  ('1. 人工知能とは', '#58a6ff', 0),
  ('2. 人工知能をめぐる動向', '#79c0ff', 1),
  ('3. 機械学習の概要', '#3fb950', 2),
  ('4. ディープラーニングの概要', '#a371f7', 3),
  ('5. ディープラーニングの要素技術', '#d2a8ff', 4),
  ('6. ディープラーニングの応用例', '#f0883e', 5),
  ('7. AIの社会実装に向けて', '#e3b341', 6),
  ('8. AIに必要な数理・統計知識', '#39c5cf', 7),
  ('9. AIに関する法律と契約', '#f85149', 8),
  ('10. AI倫理・AIガバナンス', '#ff7b72', 9)
) AS v(name, color, sort_order)
WHERE s.slug = 'g-kentei-e'
ON CONFLICT (subject_id, name) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, NULL::text, v.options::jsonb,
       0, '[0]'::jsonb, 'single', '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('g-kentei-e-q1', '1. 人工知能とは', '現在実用化されているAIの大半のように、あらかじめ決められた特定の作業に限って能力を発揮するAIを指す語はどれか。', '["特化型AI", "汎用人工知能（AGI）", "強いAI", "シンギュラリティ"]', '{"asked": "決まった一つの作業だけをこなす、今のAIの呼び名は？", "point": "一つの決まった作業だけこなすなら、特化型AI。人間並みに何でもこなす汎用人工知能はまだ未実現。", "kid": "翻訳AI・将棋AIのように、一つの仕事に特化したAI。他の仕事には使えない。", "eg": "将棋のプロ専用ソフトは将棋しか指せず、料理や会話はできない。今のAIはこの型。", "terms": [["特化型AI", "一つの決まった作業に特化して力を発揮するAI。現状の大半"], ["汎用人工知能(AGI)", "人間のように幅広い課題に柔軟に対応できる、まだ実現していないAI"]], "think": "見分けるカギは『守備範囲』。決まった一つの作業だけ＝特化型、人間並みに何でも＝汎用（未実現）。", "vs": "汎用人工知能(AGI)は人間のように幅広くこなす未実現のAI、強いAIは本物の意識や理解を持つとする哲学的立場、シンギュラリティはAIが自らを超え進歩が加速する転換点。守備範囲や論点が違う。", "usecase": "画像認識・翻訳・レコメンドなど、実務のAIはすべて特化型。用途を1つに絞るから高精度を出せる。", "opt": ["正解。一つの決まった作業に特化するのが特化型AI。今のAIの大半がこれ。", "人間のように幅広くこなす未実現のAIで、今の大半ではない。", "本物の意識を持つとする哲学的立場で、実用AIの分類ではない。", "AIが自らを超える未来の転換点で、AIの種類を指す語ではない。"]}'),
  ('g-kentei-e-q2', '1. 人工知能とは', '記号の対応表に従えば中国語で正しく応答できても、その人が中国語を理解しているとは言えない、と論じてAIの「理解」を問うた思考実験はどれか。', '["中国語の部屋", "チューリングテスト", "フレーム問題", "シンボルグラウンディング問題"]', '{"asked": "正しく答えられても意味は分かっていない、と示す思考実験の名前は？", "point": "正しく受け答えできても意味は理解していない、と示すのが中国語の部屋。", "kid": "部屋の中の人がマニュアル通りに中国語の記号を並べ替えて返すだけ。答えは合うが意味は分かっていない。", "eg": "外国語の定型文集を丸写しして返信すれば会話は成立するが、書いた本人は意味を分かっていない。", "terms": [["中国語の部屋", "正しく応答できることと意味を理解することは別、と論じたサールの思考実験"], ["強いAI", "AIが本物の理解や意識を持ちうるとする立場。中国語の部屋はこれへの批判"]], "think": "『正しく答えられること』と『意味が分かっていること』は別、と言いたい実験。この2つを切り離す点がカギ。", "vs": "チューリングテストは会話で人間と区別できるかで知能を測る方法、フレーム問題は考慮すべき事柄を絞れない難問、シンボルグラウンディング問題は記号と実物の意味が結びつかない問題。狙いが違う。", "usecase": "生成AIが流暢に答えても『理解』しているとは限らない、という議論の原点として引かれる。", "opt": ["正解。正しく応答できても意味は理解していないと示す思考実験。", "会話で人間と区別できるかで知能を判定する方法で、別物。", "考慮すべき事柄を絞れない難問で、理解の有無の話ではない。", "記号と実物の意味が結びつかない問題で、別の論点。"]}'),
  ('g-kentei-e-q3', '1. 人工知能とは', 'あるAIの仕組みが解明されて広く知られると、「それは単なる自動処理であって知能ではない」とみなされやすくなる現象はどれか。', '["AI効果", "シンギュラリティ", "トイ・プロブレム", "フレーム問題"]', '{"asked": "中身が分かると知能扱いされなくなる、人の受け取り方の変化を指す語は？", "point": "「中身が分かると急に知能扱いされなくなる」という人の受け取り方の変化なら、AI効果。", "kid": "手品もタネが分かると「なんだ」と思う。AIも仕組みが知れ渡ると「ただの計算」と見なされがち。", "eg": "かつては知能の証とされたチェスAIも、仕組みが広まると「ただの探索」と言われるようになった。", "terms": [["AI効果", "仕組みが解明・普及すると『それは知能ではない』とみなされやすくなる心理的傾向"]], "think": "ポイントは『中身が分かると知能扱いされなくなる』という人の気持ちの変化。技術そのものではなく、人がどう受け取るかの話。", "vs": "シンギュラリティはAIが自らを超える転換点、トイ・プロブレムは単純化した問題しか解けない限界、フレーム問題は考慮範囲を絞れない難問。いずれも人の受け取り方の話ではない。", "usecase": "AIの進歩を評価するとき、成果が出た途端に軽視されがちだと知っておくと冷静に見られる。", "opt": ["正解。仕組みが分かると知能扱いされなくなる、人の受け取り方の変化。", "AIが自らを超える未来の転換点で、心理的傾向ではない。", "単純化した問題しか解けない限界で、別の概念。", "考慮すべき事柄を絞れない難問で、別の概念。"]}'),
  ('g-kentei-e-q4', '1. 人工知能とは', 'AIの発展段階のうち、人が特徴を設計しなくても、注目すべき特徴そのものをデータから自ら学び取る最も進んだ段階はどれか。', '["特徴表現学習（レベル4）", "単純な制御（レベル1）", "探索と推論による問題解決", "人が特徴量を設計する機械学習（レベル3）"]', '{"asked": "特徴そのものまで自分で学ぶ、AIの最も進んだ段階は？", "point": "特徴量まで自分で見つけて学ぶなら、特徴表現学習（ディープラーニングの段階）。", "kid": "何に注目すればよいか（特徴）まで、人が教えず自分で見つける段階。深層学習がこれ。", "eg": "猫を見分けるのに『耳の形を見ろ』と人が教えなくても、AIが自分で見るべき点を見つける。", "terms": [["特徴表現学習", "注目すべき特徴そのものをデータから自ら獲得する段階。ディープラーニングが代表"], ["特徴量", "予測に効く、データの注目ポイント"]], "think": "見分けるカギは『特徴を誰が決めるか』。人が設計＝レベル3、AIが自分で獲得＝レベル4（最上位）。", "vs": "レベル1は決められた動作だけの制御、探索と推論は第1次ブームの問題解決、レベル3は人が特徴量を設計する機械学習。特徴を自分で学ぶ点でレベル4が最も進んでいる。", "usecase": "画像・音声・言語など、特徴設計が難しい分野でディープラーニングが強いのはこの性質による。", "opt": ["正解。特徴そのものを自ら学ぶ最上位の段階。", "決められた動作しかしない最も単純な段階で、逆。", "ルールに従い道筋を探す段階で、特徴を学ぶ話ではない。", "特徴量を人が設計する段階で、一歩手前。"]}'),
  ('g-kentei-e-q5', '2. 人工知能をめぐる動向', '「人工知能（Artificial Intelligence）」という言葉が初めて使われたとされる、1956年の研究者の集まりはどれか。', '["ダートマス会議", "第五世代コンピュータ計画", "ライトヒル報告", "チューリングテスト"]', '{"asked": "AIという言葉が生まれた1956年の会合の名前は？", "point": "AIという言葉の始まり・1956年なら、ダートマス会議。", "kid": "研究者が集まって「人工知能」という分野に名前を付けた、記念すべき会議。", "eg": "新しい学問の『旗揚げ式』のような集まり。ここで分野の名前が決まった。", "terms": [["ダートマス会議", "1956年、人工知能という言葉が初めて使われたとされる研究者の会合"]], "think": "カギは『AIという言葉の始まり・1956年』。技術そのものではなく、分野の名付けの出来事だと押さえる。", "vs": "第五世代コンピュータは1980年代日本の国家計画、ライトヒル報告はAI研究を批判し冬をもたらした報告、チューリングテストは知能の判定法。時代も内容も違う。", "usecase": "AIの歴史を年代で問う問題の起点として頻出。第1次ブームの始まりと結び付けて覚える。", "opt": ["正解。1956年、AIという言葉が生まれた会合。", "1980年代の日本の国家計画で、時代が違う。", "AI研究を批判した報告で、名付けの出来事ではない。", "知能を判定する方法で、会合ではない。"]}'),
  ('g-kentei-e-q6', '2. 人工知能をめぐる動向', '迷路やパズルのように単純化された問題は解けても、複雑な現実の問題には歯が立たなかった第1次AIブームの限界を象徴する語はどれか。', '["トイ・プロブレム", "シンギュラリティ", "フレーム問題", "シンボルグラウンディング問題"]', '{"asked": "おもちゃのような単純問題しか解けなかった第1次ブームの限界を指す語は？", "point": "単純化された問題は解けたが現実は無理、という第1次ブームの限界なら、トイ・プロブレム。", "kid": "きれいに整理された『おもちゃの問題』は解けても、ごちゃごちゃした現実は解けなかった。", "eg": "教科書の練習問題は解けるのに、実際の仕事の複雑さには対応できない状態。", "terms": [["トイ・プロブレム", "単純化された問題は解けても現実の複雑な問題は解けなかった、第1次ブームの限界"], ["組合せ爆発", "選択肢が増えると場合の数が爆発的に増え、計算が追いつかなくなること"]], "think": "カギは『単純化された問題は解けたが現実は無理』。原因の一つが組合せ爆発（場合の数の爆発）。", "vs": "シンギュラリティはAIが自らを超える転換点、フレーム問題は考慮範囲を絞れない難問、シンボルグラウンディング問題は記号と意味が結びつかない問題。第1次ブームの限界を指すのはトイ・プロブレム。", "usecase": "AIブームと冬の繰り返しを説明するとき、第1次ブームがなぜ退潮したかの象徴として引かれる。", "opt": ["正解。単純な問題しか解けなかった第1次ブームの限界。", "AIが自らを超える未来の転換点で、別物。", "考慮すべき事柄を絞れない難問で、別の概念。", "記号と実物の意味が結びつかない問題で、別の概念。"]}'),
  ('g-kentei-e-q7', '2. 人工知能をめぐる動向', '探索木をたどるとき、出発点に近い浅い節点をすべて調べてから、次に一段深い節点をすべて調べる、というように浅い方から順に探す方法はどれか。', '["幅優先探索", "深さ優先探索", "最良優先探索", "山登り法"]', '{"asked": "浅い層を全部調べてから次の層へ進む探索は？", "point": "浅い層を全部見てから次の層へ、なら幅優先探索。", "kid": "近いところから順に、同じ距離を全部見てから一歩先へ進む探し方。", "eg": "迷路で、分かれ道を一つずつ深追いせず、まず全部の近い道を少しずつ調べていく感じ。", "terms": [["幅優先探索", "浅い節点から順に、同じ深さを全て調べてから次の深さへ進む探索"], ["深さ優先探索", "一つの枝を行き止まりまで深く進み、詰まったら戻る探索"]], "think": "進む順で見分ける。『浅い層を全部見てから次の層へ』なら幅優先、『まず深く潜って行き止まりで戻る』なら深さ優先。", "vs": "深さ優先探索は一本道を深く進む、最良優先探索は見込みの良い方を優先、山登り法は今より良い方へ登り続ける。進む基準が違う。", "usecase": "最短経路を確実に見つけたいときは幅優先、メモリを節約したいときは深さ優先、と使い分ける。", "opt": ["正解。浅い層を全て調べてから次の層へ進む探索。", "一本道を深く進み行き止まりで戻る探索で、逆の順序。", "見込みの良い方を優先する探索で、浅い順ではない。", "今より良い方へ登り続ける手法で、探索順の話ではない。"]}'),
  ('g-kentei-e-q8', '2. 人工知能をめぐる動向', '1970年代に作られ、患者の症状から感染症を診断して抗生物質を提案した、代表的なエキスパートシステムはどれか。', '["MYCIN", "ELIZA", "Watson", "AlphaGo"]', '{"asked": "感染症を診断した第2次ブーム代表のエキスパートシステムは？", "point": "感染症診断・ルールベース・第2次ブームなら、MYCIN。", "kid": "『熱があってこの症状なら、この病気』というルールを大量に詰め込んだ診断システム。", "eg": "ベテラン医師の判断ルールを一冊のマニュアルにして、その通りに診断する仕組み。", "terms": [["MYCIN", "感染症の診断を支援した代表的なエキスパートシステム"], ["エキスパートシステム", "専門家の知識をルールの形で詰め込み、判断を模倣する仕組み"]], "think": "カギは『感染症診断・ルールベース・第2次ブーム』ならMYCIN。おうむ返しの対話プログラムELIZAとは目的が違う。", "vs": "ELIZAは相手の言葉を返す初期の対話プログラム、Watsonはクイズ番組で勝ったIBMの質問応答、AlphaGoは囲碁AI。目的も時代も違う。", "usecase": "エキスパートシステムの代表例として、ルールで知識を持たせる第2次ブームの象徴に使われる。", "opt": ["正解。感染症診断を支援した代表的エキスパートシステム。", "相手の言葉を返す初期の対話プログラムで、診断ではない。", "クイズで勝ったIBMの質問応答で、時代も目的も違う。", "囲碁AIで、エキスパートシステムではない。"]}'),
  ('g-kentei-e-q9', '2. 人工知能をめぐる動向', '第2次AIブームが退潮した一因として、専門家の知識を人手でルールにして移す作業そのものが非常に困難だったことが挙げられる。この困難を指す語はどれか。', '["知識獲得のボトルネック", "フレーム問題", "組合せ爆発", "次元の呪い"]', '{"asked": "専門家の知識を人手でルール化する作業が重すぎて詰まることを指す語は？", "point": "専門家の知識を人手でルールにする作業が重すぎて詰まる、なら知識獲得のボトルネック。", "kid": "人の頭の中の知識を、いちいち文章のルールに書き出すのが大変すぎて進まない、という壁。", "eg": "ベテランの勘を全部マニュアル化しようとすると、量が膨大で書ききれず作業が止まる。", "terms": [["知識獲得のボトルネック", "専門家の知識を人手でルール化する作業が難しく、開発の妨げになること"]], "think": "第2次ブームがつまずいた原因は、専門家の知識を人手でルールに書き出す作業があまりに大変だったこと。『人手でルール化』がキーワード。", "vs": "フレーム問題は考慮範囲を絞れない難問、組合せ爆発は場合の数の爆発、次元の呪いは高次元でデータが疎になる問題。ルール化作業の困難を指すのは知識獲得のボトルネック。", "usecase": "ルールを人が書く方式の限界を示す語。データから自ら学ぶ機械学習が主役になる伏線として語られる。", "opt": ["正解。知識を人手でルール化する作業が困難で開発の妨げになること。", "考慮すべき事柄を絞れない難問で、別の概念。", "場合の数が爆発的に増える問題で、ルール化の困難ではない。", "高次元でデータが疎になる問題で、別の概念。"]}'),
  ('g-kentei-e-q10', '2. 人工知能をめぐる動向', '2012年の画像認識コンテストで、ディープラーニングを用いて従来手法に大差をつけて優勝し、第3次AIブームの火付け役となったモデルはどれか。', '["AlexNet", "LeNet", "ResNet", "AlphaGo"]', '{"asked": "2012年に画像認識で圧勝し第3次ブームの起点になったモデルは？", "point": "2012年・画像認識・ディープラーニングで圧勝なら、AlexNet。", "kid": "深層学習の実力を世に示し、ブームに火を付けた画像認識モデル。", "eg": "無名だった選手が大会で圧勝し、その競技のやり方を一変させたような出来事。", "terms": [["AlexNet", "2012年の画像認識コンテストで圧勝し、第3次AIブームの起点となったCNN"], ["ILSVRC", "大規模画像認識の競技会。AlexNetが従来手法に大差をつけた"]], "think": "カギは『2012年・画像認識・ディープラーニングで圧勝』。第3次ブームの起点の出来事として押さえる。", "vs": "LeNetは初期の手書き数字認識CNN、ResNetは残差接続で超深層を可能にした後年のモデル、AlphaGoは囲碁AI。2012年の圧勝はAlexNet。", "usecase": "ディープラーニングが実用段階に入った転機として、第3次ブームの説明で必ず登場する。", "opt": ["正解。2012年に画像認識で圧勝し第3次ブームの起点となった。", "初期の手書き数字認識CNNで、2012年の圧勝ではない。", "後年の超深層モデルで、ブームの起点ではない。", "囲碁AIで、画像認識コンテストのモデルではない。"]}'),
  ('g-kentei-e-q11', '3. 機械学習の概要', '正解ラベルを使わず、データに潜む構造やまとまりを見つけ出す学習はどれか。', '["教師なし学習", "教師あり学習", "強化学習", "転移学習"]', '{"asked": "正解ラベル無しで、データの構造やまとまりを見つける学習は？", "point": "正解ラベルを使わず『まとめる・減らす』なら教師なし学習。", "kid": "答えを教えずに、似たもの同士をまとめたり、隠れた規則を見つけたりする学習。", "eg": "名前を教えずに写真を似た者同士に仕分けさせると、勝手にグループができる。これが教師なし。", "terms": [["教師なし学習", "正解ラベル無しで、データの構造・まとまりを見つける学習。クラスタリングや次元削減"], ["教師あり学習", "正解ラベル付きデータで、入力から正解を当てるよう学ぶ"]], "think": "見分けるカギは『正解ラベルが要るか』。まとめる・減らす（クラスタリングや次元削減）は正解不要＝教師なし。当てる（分類・回帰）は正解必要＝教師あり。", "vs": "教師あり学習は正解付きで当てる、強化学習は報酬を手がかりに試行錯誤で学ぶ、転移学習は学習済みモデルを別課題に流用する手法。正解ラベルを使わないのは教師なし。", "usecase": "顧客のグループ分け（クラスタリング）や、可視化・前処理の次元削減に使う。正解を用意できない場面で有効。", "opt": ["正解。正解ラベル無しで構造やまとまりを見つける学習。", "正解ラベルで当てる学習で、ラベルを使う。", "報酬を頼りに試行錯誤で学ぶ学習で、別の枠組み。", "学習済みモデルを流用する手法で、学習の種類ではない。"]}'),
  ('g-kentei-e-q12', '3. 機械学習の概要', '2つのグループを分ける境界のうち、最も近いデータ点との距離（マージン）が最大になる境界を選ぶ分類手法はどれか。', '["サポートベクターマシン", "k近傍法", "決定木", "主成分分析"]', '{"asked": "最も近い点との余白（マージン）を最大にして分ける分類手法は？", "point": "余白（マージン）を最大にして分けるなら、SVM。ただ分けるのではなく“一番安全な真ん中”に境界を引く。", "kid": "2つのグループの間に、両側から一番余裕を取った境界線を引く手法。", "eg": "2つの村の間に国境を引くとき、どちらの家からも一番離れた空き地のど真ん中に引くイメージ。", "terms": [["サポートベクターマシン(SVM)", "最も近い点との距離が最大になるように境界を引く分類手法"], ["マージン", "境界と、それに最も近いデータ点との距離。これを最大化する"], ["サポートベクター", "境界に最も近く、境界の位置を決めている数点"]], "think": "なぜ余白を最大にするのかがカギ。訓練データを分けるだけなら境界は何本も引けるが、本当に効かせたいのはまだ見ぬデータ。境界を片方すれすれに引くと、新しい点が少しずれただけで誤判定する。両グループの真ん中（マージン最大）に置けば、多少ずれても境界をまたぎにくい。つまりマージンの広さは未知データのズレに対する安全余裕で、広いほど汎化する。だから一番安全な真ん中に引く。", "vs": "k近傍法は境界を学ばず予測時に近いk個で多数決、決定木は条件分岐で予測、主成分分析は次元削減で分類ではない。SVMだけが『最も近い点から最も遠い境界』を選ぶ。", "usecase": "文字認識や少ないデータでの2値分類で強い。カーネル法で複雑な境界にも対応でき、深層学習普及前の主力だった。", "why_asked": "SVMは定番の教師あり分類で、k近傍法・ロジスティック回帰との取り違えが失点源。マージン最大化の理由まで問われやすい。", "opt": ["正解。マージン（最も近い点との距離）を最大にして分ける手法。", "予測時に近いk個で多数決する手法で、境界を学ばない。", "条件で枝分かれして予測する手法で、マージンの考えはない。", "次元削減の手法で、分類そのものではない。"]}'),
  ('g-kentei-e-q13', '3. 機械学習の概要', '少しずつ異なるデータで多数の決定木を作り、その多数決で予測することで精度と安定性を高める手法はどれか。', '["ランダムフォレスト", "単純パーセプトロン", "k平均法", "線形回帰"]', '{"asked": "たくさんの決定木を作って多数決する手法は？", "point": "決定木をたくさん・並列に作って多数決するなら、ランダムフォレスト（バギングの代表）。", "kid": "1本の木は間違えやすいので、少しずつ違う木を大量に作り、みんなの多数決で決める。", "eg": "一人の判断より、少しずつ意見の違う大勢の多数決の方が、極端な間違いをしにくい。", "terms": [["ランダムフォレスト", "少しずつ異なるデータで多数の決定木を作り、多数決で予測する手法"], ["バギング", "データを変えて並列に多数のモデルを作り、平均・多数決でまとめる方式"]], "think": "なぜ木をたくさん作って多数決すると強くなるのかがカギ。1本の決定木は訓練データの偏りに引きずられて過学習しやすく、木ごとに間違え方がバラバラ。少しずつ違うデータで多数の木を作ると、各自の気まぐれな間違いは方向がそろわず多数決で打ち消し合い、多くの木に共通する正しい判断だけが残る。だから1本より安定して当たる。", "vs": "単純パーセプトロンは1本の直線で分ける古典モデル、k平均法は正解なしのクラスタリング、線形回帰は数値を予測する回帰。多数の木で多数決するのはランダムフォレスト。", "usecase": "表形式データの分類・回帰で扱いやすく高精度。特徴量の重要度も出せるので実務で広く使われる。", "opt": ["正解。多数の決定木の多数決で予測する手法。", "1本の直線で分ける古典モデルで、木の集まりではない。", "正解なしでグループ分けする手法で、予測の多数決ではない。", "数値を予測する回帰で、決定木の集まりではない。"]}'),
  ('g-kentei-e-q14', '3. 機械学習の概要', '情報のばらつき（分散）をできるだけ保ちながら、多数の項目を少数の軸にまとめて次元を減らす手法はどれか。', '["主成分分析（PCA）", "k平均法", "ロジスティック回帰", "決定木"]', '{"asked": "情報をなるべく保って項目を少ない軸に減らす手法は？", "point": "情報をできるだけ保ったまま、項目を少ない軸に減らすなら、PCA。", "kid": "たくさんの項目を、大事な情報を残したまま少ない軸に圧縮する手法。", "eg": "立体の物体を、特徴が一番よく分かる角度から撮った1枚の写真にまとめるイメージ。", "terms": [["主成分分析(PCA)", "分散をできるだけ保ちつつ次元を減らす手法"], ["次元削減", "項目（次元）の数を減らして扱いやすくすること"]], "think": "カギは『情報をなるべく保って軸を減らす』ならPCA。グループを作る（クラスタリング）や、当てる（分類）と混同しない。", "vs": "k平均法はグループ分け（クラスタリング）、ロジスティック回帰は確率で分類、決定木は条件分岐で予測。次元を減らすのがPCA。", "usecase": "可視化（高次元を2〜3次元へ）、ノイズ除去、前処理での特徴圧縮に使う。", "opt": ["正解。分散を保ちつつ次元を減らす手法。", "グループ分けの手法で、次元削減ではない。", "確率で分類する手法で、軸を減らす話ではない。", "条件分岐で予測する手法で、次元削減ではない。"]}'),
  ('g-kentei-e-q15', '3. 機械学習の概要', '学習時に、重みが大きくなりすぎることへの罰則を加えて、モデルが訓練データに過剰に適合するのを抑える手法の総称はどれか。', '["正則化", "標準化", "データ拡張", "交差検証"]', '{"asked": "重みへの罰則で過学習を抑える手法の総称は？", "point": "重みが大きくなりすぎることに罰を与えて過学習を抑えるなら、正則化。", "kid": "モデルが訓練データに合わせ込みすぎないよう、重みを大きくしすぎたら罰を与えてブレーキをかける。", "eg": "暗記に頼りすぎる生徒に「丸暗記は減点」と伝えると、本質を捉えた解き方に矯正される。", "terms": [["正則化", "重みへの罰則で過学習を抑える手法の総称。L1・L2など"], ["過学習", "訓練データには高精度だが未知データで精度が落ちる状態"]], "think": "なぜ重みを大きくさせないと過学習が抑えられるのかがカギ。重みが大きいほど、入力のわずかな違いに出力が敏感に反応する。すると訓練データの細かなノイズにまで合わせにいき、未知データで大きく外す。学習時に『重みが大きいと罰を与える』項を足すと、モデルは誤差を減らすことと重みを小さく保つことを両立させようとし、必要以上に複雑な当てはめを避ける。結果、なめらかで初見に強いモデルになる。", "vs": "標準化は項目のスケールをそろえる前処理、データ拡張はデータを水増しする手法、交差検証は評価の方法。過学習を罰則で抑えるのが正則化。", "usecase": "L1は効かない項目の重みを0にして特徴選択、L2は全体をなだらかに小さくする。深層学習でも標準的に使う。", "opt": ["正解。重みへの罰則で過学習を抑える手法の総称。", "項目のスケールをそろえる前処理で、罰則ではない。", "データを水増しする手法で、罰則の話ではない。", "評価の方法で、過学習を抑える罰則ではない。"]}'),
  ('g-kentei-e-q16', '3. 機械学習の概要', 'データをk個の部分に分け、そのうち1つを検証・残りを訓練に使うことをk回繰り返して評価を平均する手法はどれか。', '["k分割交差検証", "ホールドアウト法", "ブートストラップ法", "グリッドサーチ"]', '{"asked": "データを分け、検証役を交代させて何度も測り平均する手法は？", "point": "分けて・テスト役を交代・平均するなら、交差検証。", "kid": "データをk組に分け、順番に1組ずつを本番テスト役にして、k回測って平均する。", "eg": "5人で持ち回りで審査員役を交代しながら採点し、平均を取れば偏りが減る。", "terms": [["k分割交差検証", "データをk分割し、検証役を交代させてk回評価し平均する手法"], ["ホールドアウト法", "データを訓練用とテスト用に一度だけ分ける手法"]], "think": "カギは『分けて・テスト役を交代・平均』なら交差検証。『一度だけ分けて終わり』ならホールドアウト。", "vs": "ホールドアウト法は一度だけ分ける、ブートストラップ法は復元抽出で標本を作る、グリッドサーチは設定値の総当たり探索。検証役を交代して平均するのが交差検証。", "usecase": "データが少なく、分け方のたまたまに評価が左右されるのを避けたいときに有効。", "opt": ["正解。検証役を交代させてk回評価し平均する手法。", "一度だけ訓練とテストに分ける手法で、交代しない。", "復元抽出で標本を作る手法で、評価の交代ではない。", "設定値の総当たり探索で、評価法ではない。"]}'),
  ('g-kentei-e-q17', '3. 機械学習の概要', '複数の弱い学習器を、直前の学習器が間違えた事例を重視しながら順番に追加していくアンサンブル手法はどれか。', '["ブースティング", "バギング", "スタッキング", "ドロップアウト"]', '{"asked": "前の間違いを重視して学習器を順番に足していく手法は？", "point": "前の間違いを重視して、学習器を順番に足していくなら、ブースティング。", "kid": "前の生徒が間違えた問題を、次の生徒が重点的に復習していく、リレー式の学習。", "eg": "苦手問題に印を付け、次の担当者がそこを重点的に補強していくやり方。", "terms": [["ブースティング", "前の学習器の誤りを重視し、順番に学習器を足していくアンサンブル"], ["バギング", "データを変えて並列に学習器を作り、多数決でまとめる"]], "think": "見分けるカギは『順番か並列か』。前の失敗を受けて順番に足す＝ブースティング、バラバラに作って多数決＝バギング。", "vs": "バギングは並列に作って多数決、スタッキングは複数モデルの出力をさらに別モデルでまとめる、ドロップアウトは過学習対策。順番に誤りを補うのはブースティング。", "usecase": "勾配ブースティング（XGBoostなど）は表データのコンペで強力。精度を追うときの定番。", "opt": ["正解。前の誤りを重視し順番に学習器を足す手法。", "並列に作って多数決する手法で、順番ではない。", "出力を別モデルでまとめる手法で、逐次補強ではない。", "過学習対策で、アンサンブルの方式ではない。"]}'),
  ('g-kentei-e-q18', '4. ディープラーニングの概要', 'ニューラルネットワークの各ノードで、入力の合計を変換して出力する活性化関数を置く主な目的はどれか。', '["非線形性を導入し、複雑な関係を表せるようにするため", "各層に入る値の分布を一定範囲にそろえて学習を安定させるため", "更新の歩幅である学習率を自動で調整するため", "一部のノードを休ませて過学習を抑えるため"]', '{"asked": "活性化関数を置く主な目的は？", "point": "非線形性を加えて複雑な関係を表せるようにするのが、活性化関数の役割。", "kid": "まっすぐな関係しか作れない層に『曲がり』を与えて、複雑なパターンを表せるようにする部品。", "eg": "定規（直線）だけでは曲線は描けない。曲げる道具を足して初めて複雑な形が描ける。", "terms": [["活性化関数", "入力の合計を非線形に変換して出力する関数。ReLUやシグモイドなど"], ["非線形性", "入力と出力が直線関係にないこと。層を重ねる意味を生む"]], "think": "なぜ活性化関数が要るのかがカギ。活性化関数が無いと、層をいくら重ねても全体は結局1つの直線的な変換にしかならず、層を深くする意味がない。各ノードに非線形な変換を挟むと、層を重ねるたびに表現できる形が複雑になり、曲がった境界や入り組んだパターンも表せる。だから複雑な関係を学ぶには非線形の活性化関数が不可欠。", "vs": "値の分布をそろえるのはバッチ正規化、学習率の自動調整は最適化手法、ノードを休ませるのはドロップアウト。非線形性を加えるのが活性化関数の役割。", "usecase": "ReLUは勾配消失に強く深い層で標準、シグモイドは二値の確率出力、ソフトマックスは多クラスの確率出力に使う。", "opt": ["正解。非線形性を加え、複雑な関係を表せるようにするため。", "それはバッチ正規化の役割で、活性化関数の主目的ではない。", "それは最適化手法の役割で、活性化関数の目的ではない。", "それはドロップアウトの役割で、活性化関数の目的ではない。"]}'),
  ('g-kentei-e-q19', '4. ディープラーニングの概要', '層が深いネットワークで、シグモイド関数を活性化関数に使うと学習が進みにくくなる主な原因はどれか。', '["勾配消失", "過学習", "次元の呪い", "データリーケージ"]', '{"asked": "深い層でシグモイドを使うと学習が進みにくくなる原因は？", "point": "学習の『直してね』の合図が、深い層を伝わるうちに小さくなって消える。これが勾配消失。", "kid": "間違いを直す合図が、層を通るたびに小さくされて、手前の層まで届かなくなる現象。", "eg": "伝言ゲームで、後ろに行くほど声が小さくなり、最後には何も聞こえなくなる。", "terms": [["勾配消失", "勾配（学習の信号）が層を伝わるうちに小さくなり、手前の層が学べなくなる問題"], ["ReLU", "プラスはそのまま通し、勾配が消えにくい活性化関数"]], "think": "なぜシグモイドで消えるのかがカギ。学習の『直してね』の合図（勾配）は、活性化関数の傾きを掛けながら層を伝わる。シグモイドは一番効くところでも傾きが4分の1以下しかなく、層を通るたび合図が縮み、深いと消えてしまう。手前の層まで合図が届かないと重みを直せず、学べない。傾きが1のReLUに替えると和らぐ。", "vs": "過学習は訓練に合わせすぎる問題、次元の呪いは高次元でデータが疎になる問題、データリーケージは答えの漏れ。深い層で信号が消えるのは勾配消失。", "usecase": "対策としてReLU系の活性化関数、バッチ正規化、残差接続（スキップ結合）が使われる。", "opt": ["正解。勾配が層を伝わるうちに消え、手前が学べなくなる。", "訓練に合わせすぎる問題で、信号が消える話ではない。", "高次元でデータが疎になる問題で、別の概念。", "答えが漏れる問題で、勾配の消失ではない。"]}'),
  ('g-kentei-e-q20', '4. ディープラーニングの概要', 'ニューラルネットワークの学習で、出力の誤差を出力層から入力層へ向かって伝えながら、各重みの勾配を求める手法はどれか。', '["誤差逆伝播法", "主成分分析", "焼きなまし法", "k近傍法"]', '{"asked": "誤差を出口から入口へさかのぼらせて各重みの直し方を求める手法は？", "point": "誤差を出口から入口へさかのぼらせ、各重みの直し方を求めるなら、誤差逆伝播法。", "kid": "出口で出た間違いを、入口に向かって一層ずつさかのぼらせ、各重みの直し方を計算する。", "eg": "料理の味の失敗を、盛り付けから調理、仕込みへと逆にたどって、どの工程が原因かを突き止める。", "terms": [["誤差逆伝播法", "誤差を出力層から入力層へ伝え、各重みの勾配を求める手法"], ["連鎖律", "合成関数の微分の規則。逆伝播を数学的に支える"]], "think": "なぜ出口から入口へさかのぼるのかがカギ。各重みを直すには『その重みを動かすと最終誤差がどれだけ変わるか（勾配）』が要る。ネットワークは入口から出口へ関数を重ねた入れ子構造なので、出口側の誤差から連鎖律で1層ずつ手前へ掛け算していくと、途中の計算を使い回しながら全部の重みの勾配を一度に求められる。前向きに求め直すより圧倒的に速い。", "vs": "主成分分析は次元削減、焼きなまし法は最適化の探索手法、k近傍法は分類手法。誤差をさかのぼらせて勾配を求めるのが誤差逆伝播法。", "usecase": "ニューラルネットワーク学習の中核。これがあるから多層でも効率よく重みを更新できる。", "opt": ["正解。誤差を出口から入口へ伝えて各重みの勾配を求める。", "次元削減の手法で、勾配計算ではない。", "最適化の探索手法で、逆伝播ではない。", "分類手法で、勾配を求める手法ではない。"]}'),
  ('g-kentei-e-q21', '4. ディープラーニングの概要', '代表的な最適化手法であるAdamが、利点を組み合わせているとされる2つの手法はどれか。', '["モメンタムとRMSProp", "ドロップアウトとバッチ正規化", "L1正則化とL2正則化", "早期終了と重み初期化"]', '{"asked": "Adamが組み合わせている2つの工夫は？", "point": "Adamは『勢い（モメンタム）』と『歩幅の自動調整（RMSProp）』の合わせ技。", "kid": "進む方向に勢いをつける工夫と、方向ごとに歩幅を調整する工夫を、両取りした最適化手法。", "eg": "坂を下るとき、勢いをつけて速く進みつつ、急な所では歩幅を狭めて転ばないようにする。", "terms": [["Adam", "モメンタムとRMSPropの利点を組み合わせた最適化手法"], ["モメンタム", "過去の進行方向を引き継ぎ、揺れを抑えて速く進む工夫"]], "think": "カギは『勢い＋歩幅の自動調整』。進む方向（勢い）と歩幅の両方を賢くしたのがAdam、と押さえる。", "vs": "ドロップアウトとバッチ正規化は過学習・安定化の手法、L1とL2は正則化、早期終了と重み初期化も別の工夫。Adamが束ねるのはモメンタムとRMSProp。", "usecase": "多くの深層学習で既定の最適化手法として広く使われる。調整が少なくても安定して速い。", "opt": ["正解。勢い（モメンタム）と歩幅調整（RMSProp）の合わせ技。", "過学習・安定化の手法で、最適化の勢いと歩幅ではない。", "どちらも正則化で、最適化の2工夫ではない。", "別々の工夫で、Adamが束ねる2つではない。"]}'),
  ('g-kentei-e-q22', '4. ディープラーニングの概要', '学習のたびに一部のノードをランダムに無効化することで、過学習を抑える手法はどれか。', '["ドロップアウト", "バッチ正規化", "データ拡張", "勾配クリッピング"]', '{"asked": "学習のたびにノードをランダムに休ませて過学習を抑える手法は？", "point": "学習のたびに一部のノードをランダムに休ませて過学習を抑えるなら、ドロップアウト。", "kid": "毎回一部のノードをサボらせることで、特定のノードに頼りきらない賢いネットワークにする。", "eg": "毎回メンバーを一部欠席にして練習すると、誰か一人に頼らず全員が力をつけるチームになる。", "terms": [["ドロップアウト", "学習のたびに一部のノードをランダムに無効化する過学習対策"]], "think": "なぜランダムに休ませると過学習が減るのかがカギ。全ノードが常にそろうと、特定のノード同士がいつも一緒に働く前提で結託し、訓練データの細かい癖まで覚え込む。学習のたびに一部を無効化すると、どのノードが居るか毎回変わるので、少数の相棒に頼れず、一つひとつが単独でも効く特徴を学ぶ。さらに毎回違う構成を学ぶことになり、その平均をとる効果で初見データに強くなる。", "vs": "バッチ正規化は入力分布をそろえる、データ拡張はデータを水増しする、勾配クリッピングは勾配爆発を抑える。ノードをランダムに休ませるのはドロップアウト。", "usecase": "全結合層で特に効く定番の過学習対策。推論時は全ノードを使い、学習時だけ無効化する。", "opt": ["正解。ノードをランダムに無効化して過学習を抑える。", "入力の分布をそろえる手法で、ノードを休ませない。", "データを水増しする手法で、ノードの無効化ではない。", "勾配爆発を抑える手法で、過学習対策の主役ではない。"]}'),
  ('g-kentei-e-q23', '4. ディープラーニングの概要', '一回の更新で重みをどれだけ大きく動かすかを決める値で、大きすぎると発散し、小さすぎると学習が遅くなるものはどれか。', '["学習率", "エポック数", "バッチサイズ", "ドロップアウト率"]', '{"asked": "更新の歩幅を決める値で、大きすぎ発散・小さすぎ低速なものは？", "point": "更新の歩幅・大きすぎると発散、小さすぎると遅い、なら学習率。", "kid": "坂を下る一歩の大きさ。大股すぎると谷を飛び越え、小股すぎるとなかなか着かない。", "eg": "目的地へ歩くとき、歩幅が大きすぎると通り過ぎ、小さすぎると時間がかかる。", "terms": [["学習率", "1回の更新で重みを動かす大きさ（歩幅）を決める値"], ["ハイパーパラメータ", "学習前に人が決める設定値。学習率や層数など"]], "think": "カギは『更新の歩幅・大きすぎると発散、小さすぎると遅い』なら学習率。何回データを回すか（エポック）や小分けの大きさ（バッチサイズ）とは別物。", "vs": "エポック数はデータを何周するか、バッチサイズは1回の更新に使う量、ドロップアウト率は休ませる割合。更新の歩幅を決めるのが学習率。", "usecase": "最も影響の大きいハイパーパラメータの一つ。Adamなどは各方向の歩幅を自動調整して扱いやすくする。", "opt": ["正解。更新の歩幅を決める値。大きすぎ発散・小さすぎ低速。", "データを何周するかの回数で、歩幅ではない。", "1回の更新に使うデータ量で、歩幅ではない。", "ノードを休ませる割合で、更新の歩幅ではない。"]}'),
  ('g-kentei-e-q24', '5. ディープラーニングの要素技術', '同じフィルタを画像全体でずらしながら使い回し、位置によらず局所的な特徴を捉えるCNNの層はどれか。', '["畳み込み層", "プーリング層", "全結合層", "回帰結合層"]', '{"asked": "フィルタを使い回して局所の特徴を拾うCNNの層は？", "point": "同じフィルタを画像じゅうで使い回し、場所によらず局所の特徴を拾うなら、畳み込み層。", "kid": "小さな虫眼鏡（フィルタ）を画像の上でずらしながら、線や角などの特徴を拾っていく層。", "eg": "同じ型抜きを紙の上をずらしながら押し当て、どこに同じ模様があるか探すイメージ。", "terms": [["畳み込み層", "フィルタを画像全体でずらし、局所的な特徴を捉える層"], ["フィルタ", "特徴（線・角など）を検出する小さな重みの窓"]], "think": "なぜ同じフィルタを使い回すのかがカギ。『縦線』や『角』は画像のどこに現れても同じ特徴。位置ごとに別々の重みを用意すると、左上の縦線と右下の縦線を別物として学び直すことになり、重みが膨大で非効率。1枚のフィルタを全域でスライドさせて使い回せば、場所が変わっても同じ特徴を拾え、覚える重みも激減する。だから少ないパラメータで効率よく特徴を捉えられる。", "vs": "プーリング層は領域を代表値でまとめて縮小、全結合層は全ノードをつなぐ、回帰結合層は系列を順に処理する。フィルタを使い回すのは畳み込み層。", "usecase": "画像認識の基盤。層が深くなるほど、エッジから模様、物体の部品へと複雑な特徴を捉える。", "opt": ["正解。フィルタを使い回して局所の特徴を拾う層。", "領域を代表値でまとめて縮小する層で、特徴抽出の主役ではない。", "全ノードをつなぐ層で、フィルタの使い回しはしない。", "系列を順に処理する層で、画像の局所特徴ではない。"]}'),
  ('g-kentei-e-q25', '5. ディープラーニングの要素技術', '小さな領域を代表値でまとめて特徴マップを縮小し、多少の位置ずれに強くするCNNの層はどれか。', '["プーリング層", "畳み込み層", "全結合層", "正規化層"]', '{"asked": "特徴を粗くまとめて縮め、位置ずれに強くする層は？", "point": "拾った特徴を粗くまとめて縮め、位置が多少ずれても拾えるようにするなら、プーリング。", "kid": "細かい特徴マップを、小さな区画ごとに代表値でまとめて小さくする層。", "eg": "細かい地図を、区画ごとの代表点だけ残した粗い地図にまとめるイメージ。多少ずれても大勢に影響しない。", "terms": [["プーリング層", "小領域を代表値でまとめ、特徴マップを縮小する層"], ["最大値プーリング", "小領域の最大値だけを残す代表的なプーリング"]], "think": "なぜ縮めると位置ずれに強くなるのかがカギ。最大値プーリングは小さな領域の中で一番強く反応した値だけを残す。特徴が数ピクセルずれても、その領域に入ってさえいれば最大値は変わらないので出力も変わらない。つまり多少の位置ずれを吸収できる。あわせてサイズが縮むので計算量も減る。", "vs": "畳み込み層は新しい特徴を拾う、全結合層は全ノードをつなぐ、正規化層は値のばらつきをそろえる。縮小して位置ずれに強くするのはプーリング。", "usecase": "畳み込み層と交互に重ね、位置ずれへの頑健性と計算量削減を両立する。", "opt": ["正解。特徴を粗くまとめて縮め、位置ずれに強くする層。", "新しい特徴を拾う層で、縮小が主目的ではない。", "全ノードをつなぐ層で、縮小の役割ではない。", "値のばらつきをそろえる層で、位置ずれ対策ではない。"]}'),
  ('g-kentei-e-q26', '5. ディープラーニングの要素技術', '通常のRNNが苦手とする長い系列の依存関係を、ゲートと記憶セルを導入することで保てるようにした手法はどれか。', '["LSTM", "CNN", "オートエンコーダ", "サポートベクターマシン"]', '{"asked": "ゲートと記憶で長い系列を扱えるようにしたRNNの発展形は？", "point": "門（ゲート）と記憶で長い情報を保ち、勾配消失に対処するのがLSTM。", "kid": "必要な情報を長く覚えておける『記憶』と、覚える・忘れるを調整する『門』を足したRNN。", "eg": "大事なメモは金庫（記憶セル）に入れて長く保ち、必要な時だけ出し入れする（門）。", "terms": [["LSTM", "ゲートと記憶セルで長い系列の依存を保てるようにしたRNN"], ["ゲート", "何を覚え・忘れ・出すかを調整する仕組み"]], "think": "なぜ門と記憶で勾配消失に対処できるのかがカギ。通常のRNNは前の状態に毎回重みを掛け直して伝えるため、長い系列では掛け算が積み重なって合図（勾配）が消え、遠い過去を学べない。LSTMは情報をそのまま通す記憶（セル）の通路を持ち、掛け算ではなく足し込みで更新するので合図が薄まりにくい。さらに門が何を覚え・忘れ・出すかを調整するので、必要な情報だけ遠くまで届く。", "vs": "CNNは画像の局所特徴を拾う、オートエンコーダは圧縮・復元、SVMは分類手法。長い系列を扱うRNNの発展形はLSTM。", "usecase": "機械翻訳や音声認識など、順番のあるデータで長い文脈が要る場面で使われた（近年はTransformerが主流）。", "opt": ["正解。ゲートと記憶で長い系列の依存を保つRNNの発展形。", "画像の局所特徴を拾う手法で、系列向けではない。", "圧縮・復元を学ぶ手法で、系列の記憶が主眼ではない。", "分類手法で、系列を保つ仕組みではない。"]}'),
  ('g-kentei-e-q27', '5. ディープラーニングの要素技術', '系列の各要素が、同じ系列内の他の要素のどれにどの程度注目すべきかを重み付けして表現を作る仕組みはどれか。', '["自己注意（Self-Attention）", "プーリング", "ドロップアウト", "バッチ正規化"]', '{"asked": "同じ文の中で、単語どうしの関係の強さを測る仕組みは？", "point": "同じ系列の中で、要素どうしがどれだけ注目し合うかを測るなら、自己注意。", "kid": "文の中で、ある単語が他のどの単語と関係が深いかを、その場で重み付けして捉える仕組み。", "eg": "『それ』が文中の何を指すか、周りの単語との関係の強さを見て判断するイメージ。", "terms": [["自己注意(Self-Attention)", "同じ系列内の要素どうしの関係の強さを重み付けする仕組み"], ["Attention", "注目すべき箇所に重みを置いて参照する仕組みの総称"]], "think": "カギは『同じ系列の中で、要素どうしがどれだけ注目し合うか』なら自己注意。関係の強さをその場で測るのが特徴で、Transformerの中核をなす。", "vs": "プーリングは特徴の縮小、ドロップアウトは過学習対策、バッチ正規化は分布の安定化。要素どうしの関係を測るのは自己注意。", "usecase": "Transformerの中核。文中の離れた単語の関係も直接捉えられ、並列計算もしやすい。", "opt": ["正解。同じ系列内で要素どうしの関係の強さを測る仕組み。", "特徴を縮小する処理で、関係を測るものではない。", "過学習対策で、注目の仕組みではない。", "分布を安定化する処理で、関係を測るものではない。"]}'),
  ('g-kentei-e-q28', '5. ディープラーニングの要素技術', 'RNNのように前から順に処理するのではなく、系列全体を一度に見て並列に計算できる点を主な強みとするモデルはどれか。', '["Transformer", "LSTM", "単純パーセプトロン", "オートエンコーダ"]', '{"asked": "系列全体を一度に見て並列計算できるのが強みのモデルは？", "point": "系列全体を一度に見て並列に計算できるのが、Transformerの強み。", "kid": "一語ずつ順番に読むRNNと違い、文全体を一度に見て並列に処理できるモデル。", "eg": "本を1ページずつ順に読むのではなく、見開き全体を一目で把握するイメージ。だから速い。", "terms": [["Transformer", "自己注意を用い、系列全体を並列処理する言語モデルの基盤"], ["自己注意", "系列内の要素どうしの関係を測る仕組み。Transformerの中核"]], "think": "なぜ並列にできるのかがカギ。RNNは前の出力を次の入力に使うため、前から一語ずつしか進めず遅い。Transformerは自己注意で系列内の全要素の関係を一度にまとめて計算するので、順番を待たずに並列処理できる。だから大規模化・高速化がしやすく、長い文脈の関係も直接捉えられる。", "vs": "LSTMは前から順に処理するRNNの発展形、単純パーセプトロンは古典的な分類、オートエンコーダは圧縮・復元。並列処理が強みなのはTransformer。", "usecase": "BERTやGPTなど大規模言語モデルの土台。翻訳・要約・生成など言語処理の主流。", "opt": ["正解。系列全体を一度に見て並列計算できるのが強み。", "前から順に処理するRNNの発展形で、並列ではない。", "古典的な分類モデルで、系列処理の話ではない。", "圧縮・復元を学ぶ手法で、並列処理が主眼ではない。"]}'),
  ('g-kentei-e-q29', '5. ディープラーニングの要素技術', '入力を低次元の表現へ圧縮し、そこから元の入力を復元するように学習することで、データの特徴を捉えるネットワークはどれか。', '["オートエンコーダ", "サポートベクターマシン", "決定木", "ランダムフォレスト"]', '{"asked": "入力を圧縮して元に戻すよう学び、特徴を捉えるネットワークは？", "point": "入力を圧縮し、そこから元に戻すよう学ぶなら、オートエンコーダ。", "kid": "情報をいったん小さくまとめ、そこから元通りに復元する練習で、大事な特徴をつかむ。", "eg": "絵を見て要点だけメモし、そのメモだけで元の絵を描き直す練習。うまく描ければ要点をつかめた証拠。", "terms": [["オートエンコーダ", "入力を圧縮し、そこから元に戻すよう学んで特徴を捉えるネットワーク"], ["VAE", "中身を確率分布として扱い、生成にも使えるようにした発展版"]], "think": "カギは『圧縮して元に戻す』を目標にするならオートエンコーダ。入力と出力が同じになるのを目指す点が特徴。ボトルネックで無理やり圧縮させることで、重要な特徴だけが残る。", "vs": "SVMは境界を学ぶ分類、決定木は条件分岐で予測、ランダムフォレストは木の多数決。圧縮・復元の構造を持つのはオートエンコーダ。", "usecase": "異常検知（正常データはうまく戻せるが異常は戻せない）、ノイズ除去、次元削減に使う。", "opt": ["正解。入力を圧縮して元に戻すよう学ぶネットワーク。", "境界を学ぶ分類手法で、圧縮・復元ではない。", "条件分岐で予測する手法で、復元を学ばない。", "木の多数決で予測する手法で、圧縮・復元ではない。"]}'),
  ('g-kentei-e-q30', '6. ディープラーニングの応用例', '画像に写る複数の物体それぞれについて、その種類と位置（囲む枠）を同時に求めるタスクはどれか。', '["物体検出", "画像分類", "セマンティックセグメンテーション", "姿勢推定"]', '{"asked": "複数の物体の種類と位置（枠）を同時に答えるタスクは？", "point": "物の種類と位置（枠）を同時に答えるなら、物体検出。", "kid": "写真の中の物を、四角い枠で囲んで『これは何』と種類も当てるタスク。", "eg": "防犯カメラ映像で、人や車を四角で囲んでラベルを付けるイメージ。", "terms": [["物体検出", "複数の物体の種類と位置（枠）を同時に求めるタスク"], ["画像分類", "写真全体に1つのラベルを付けるタスク"]], "think": "カギは『複数の物＋位置（枠）』なら物体検出。写真全体に1ラベルは画像分類、画素ごとに塗り分けはセグメンテーション。", "vs": "画像分類は写真全体に1ラベル、セマンティックセグメンテーションは画素ごとに塗り分け、姿勢推定は関節位置の推定。枠で種類と位置を出すのは物体検出。", "usecase": "自動運転（歩行者・車の検出）、監視、製造の外観検査などで使う。YOLOやSSDが代表。", "opt": ["正解。複数の物体の種類と位置を枠で同時に求めるタスク。", "写真全体に1ラベルを付けるタスクで、位置は出さない。", "画素ごとに塗り分けるタスクで、枠ではない。", "関節位置を推定するタスクで、物体の種類当てではない。"]}'),
  ('g-kentei-e-q31', '6. ディープラーニングの応用例', '画像の画素一つひとつに、それがどのクラスに属するかのラベルを割り当てるタスクはどれか。', '["セマンティックセグメンテーション", "物体検出", "画像分類", "超解像"]', '{"asked": "画素ごとにクラスのラベルを塗り分けるタスクは？", "point": "画素ひとつずつにラベルを塗り分けるなら、セマンティックセグメンテーション。", "kid": "写真を、この画素は道路・この画素は空、と塗り絵のように領域で塗り分けるタスク。", "eg": "地図を、緑は森・青は水と色分けするように、画像を意味ごとに塗り分ける。", "terms": [["セマンティックセグメンテーション", "画素ごとにクラスのラベルを割り当てるタスク"], ["インスタンスセグメンテーション", "同じクラスでも個体ごとに区別して領域を分けるタスク"]], "think": "カギは『画素ごとにラベル』ならセグメンテーション。枠で囲むだけの物体検出よりも細かい。", "vs": "物体検出は枠で囲む、画像分類は写真全体に1ラベル、超解像は画像を高解像度化する。画素ごとに塗り分けるのはセグメンテーション。", "usecase": "自動運転の走行可能領域の把握、医療画像での臓器・病変の領域抽出などに使う。", "opt": ["正解。画素ごとにクラスのラベルを割り当てるタスク。", "枠で囲むタスクで、画素ごとではない。", "写真全体に1ラベルを付けるタスクで、塗り分けではない。", "画像を鮮明にするタスクで、ラベル付けではない。"]}'),
  ('g-kentei-e-q32', '6. ディープラーニングの応用例', 'Transformerに基づく言語モデルのうち、文の前後両方を見て意味を理解することを得意とする代表的なモデルはどれか。', '["BERT", "GPT", "word2vec", "ResNet"]', '{"asked": "文の前後両方を見て意味を理解するのが得意なモデルは？", "point": "前後を見て理解する型がBERT、前から次の語を予想して生成する型がGPT。", "kid": "穴埋め問題のように、前後の文脈から意味を読み取るのが得意なモデル。", "eg": "『私は__を飲む』の空欄を、前後を見て『水』などと当てるような理解の仕方。", "terms": [["BERT", "文の前後両方を見て意味を理解する双方向の言語モデル"], ["GPT", "前から次の語を予測して文章を生成する言語モデル"]], "think": "見分けるカギは『見る向き』。前後の両方＝BERT（理解型）、前から次へ＝GPT（生成型）。", "vs": "GPTは前から次の語を予測する生成型、word2vecは単語をベクトル化する古い手法、ResNetは画像認識のCNN。前後を見て理解するのはBERT。", "usecase": "文の分類、検索、質問応答など『理解』が主のタスクで強い。", "opt": ["正解。前後両方を見て意味を理解する双方向モデル。", "前から次の語を予測して生成する型で、向きが違う。", "単語をベクトル化する手法で、文脈理解のモデルではない。", "画像認識のCNNで、言語モデルではない。"]}'),
  ('g-kentei-e-q33', '6. ディープラーニングの応用例', '単語を、その意味的な近さが距離に反映される密なベクトルとして表現する手法の代表例はどれか。', '["word2vec", "one-hotエンコーディング", "主成分分析", "決定木"]', '{"asked": "意味の近さが距離に表れる、単語の密なベクトル表現の代表例は？", "point": "意味の近さが距離に表れる、密なベクトル表現なら、word2vec。", "kid": "『王』と『女王』のように意味が近い単語が、数値の空間でも近くに来るように表す手法。", "eg": "地図上で、似た街どうしを近くに配置するように、似た意味の単語を近くに置く。", "terms": [["word2vec", "意味の近さが距離に表れる、単語の分散表現を学ぶ代表的手法"], ["分散表現", "単語を密なベクトルで表し、意味の近さを距離で扱えるようにしたもの"]], "think": "カギは『意味の近さが距離に出る、ぎっしり詰まった数値表現』なら分散表現＝word2vec。数える系（one-hotなど）は意味の近さを表せない。", "vs": "one-hotエンコーディングは1か所だけ1の疎なベクトルで意味の近さを表せない、主成分分析は次元削減、決定木は分類。意味を距離で表すのはword2vec。", "usecase": "検索、類似語の発見、後段のニューラルネットへの入力（埋め込み）に使う。", "opt": ["正解。意味の近さが距離に表れる密なベクトル表現。", "1か所だけ1の疎な表現で、意味の近さを表せない。", "次元削減の手法で、単語のベクトル表現ではない。", "分類手法で、意味の距離を表すものではない。"]}'),
  ('g-kentei-e-q34', '6. ディープラーニングの応用例', '生成器と識別器を競わせ、識別器を欺くほど本物らしいデータを生成器に学習させる生成モデルはどれか。', '["敵対的生成ネットワーク（GAN）", "オートエンコーダ", "決定木", "サポートベクターマシン"]', '{"asked": "作る側と見破る側を競わせて本物そっくりを作らせる生成モデルは？", "point": "作る側と見破る側を競わせて本物そっくりを目指すなら、GAN。", "kid": "偽物を作る役と、それを見破る役を競わせ、いたちごっこで本物級の生成を学ばせる。", "eg": "ニセ札職人と鑑定士のいたちごっこ。鑑定士を何度もだますうちに職人の腕が本物級になる。", "terms": [["敵対的生成ネットワーク(GAN)", "生成器と識別器を競わせ、本物そっくりのデータを作らせるモデル"], ["識別器", "入力が本物か偽物かを見分ける役。生成器と競う"]], "think": "なぜ競わせると本物そっくりになるのかがカギ。生成器は『識別器をだませたか』を手がかりに学ぶ。識別器は本物と偽物を見分けようとどんどん賢くなるので、だますためのハードルが自動的に上がり続ける。生成器はその上がり続ける基準を超えようと改善を迫られ、結果として本物との差が縮まっていく。人が正解の絵を用意しなくても、識別器が動く採点者の役をするのがミソ。", "vs": "オートエンコーダは圧縮・復元を学ぶが競わせる仕組みではない、決定木とSVMは分類手法。競わせて生成するのはGAN。", "usecase": "リアルな顔画像の生成、超解像、データの水増しに使う。ディープフェイクの技術的土台でもある。", "opt": ["正解。生成器と識別器を競わせて本物そっくりを作らせる。", "圧縮・復元を学ぶ生成系だが、競わせる仕組みではない。", "分類手法で、生成モデルではない。", "分類手法で、データを作るモデルではない。"]}'),
  ('g-kentei-e-q35', '6. ディープラーニングの応用例', 'データに加えたノイズを段階的に取り除くよう学習し、最終的にノイズから高品質な画像を生成する生成モデルはどれか。', '["拡散モデル", "サポートベクターマシン", "ランダムフォレスト", "ロジスティック回帰"]', '{"asked": "ノイズを少しずつ取り除いて画像を作る生成モデルは？", "point": "ノイズを少しずつ取り除いて画像を作るなら、拡散モデル。", "kid": "砂嵐だらけの画面から、少しずつノイズを消して、最後にくっきりした絵を浮かび上がらせる。", "eg": "曇ったガラスを少しずつ拭くと、向こうの景色がだんだんくっきり見えてくる。", "terms": [["拡散モデル", "わざとノイズを加える手順を逆にたどり、ノイズから画像を作るモデル"], ["ノイズ除去", "各段階で加わったノイズを予想して取り除く、拡散モデルの学習の要"]], "think": "カギは『ノイズを足す手順を逆にたどって取り除く』なら拡散モデル。近ごろの高品質な画像生成の主流。GANより学習が安定しやすい。", "vs": "SVMは分類、ランダムフォレストは木の多数決、ロジスティック回帰は確率で分類。ノイズから画像を作るのは拡散モデル。", "usecase": "Stable DiffusionやDALL-Eなど画像生成AIの主流。テキストからの画像生成の中心技術。", "opt": ["正解。ノイズを段階的に取り除いて画像を作る生成モデル。", "分類手法で、画像を生成するモデルではない。", "木の多数決で予測する手法で、生成モデルではない。", "確率で分類する手法で、画像生成ではない。"]}'),
  ('g-kentei-e-q36', '6. ディープラーニングの応用例', '大量のデータで事前学習した既存モデルを別の課題に流用し、少ないデータと計算で高い性能を得る手法はどれか。', '["転移学習", "データ拡張", "アンサンブル学習", "交差検証"]', '{"asked": "学習済みモデルを別課題に流用して少ないデータで性能を出す手法は？", "point": "学習済みモデルを別の課題に流用するなら、転移学習。", "kid": "すでに学び終えたモデルの知識を土台にして、新しい課題を少ない労力で解けるようにする。", "eg": "英語を習得済みの人が、似た言語を短期間で覚えられるように、既存の知識を土台に使う。", "terms": [["転移学習", "事前学習済みモデルを別の課題に流用する手法"], ["ファインチューニング", "転移学習の中で、流用したモデルの重みを新課題に合わせて微調整すること"]], "think": "カギは『学習済みの知識を別課題に使い回す』なら転移学習。ファインチューニングはその中で重みを微調整する具体手法で、包む向きを逆にしない。", "vs": "データ拡張はデータを水増しする手法、アンサンブル学習は複数モデルを組み合わせる手法、交差検証は評価法。学習済みモデルを流用するのは転移学習。", "usecase": "データが少ない現場で定番。画像や言語の大規模事前学習モデルを土台に、自社課題へ適用する。", "opt": ["正解。学習済みモデルを別課題に流用する手法。", "データを水増しする手法で、モデルの流用ではない。", "複数モデルを組み合わせる手法で、流用ではない。", "評価の方法で、モデルの流用ではない。"]}'),
  ('g-kentei-e-q37', '7. AIの社会実装に向けて', 'AIプロジェクトで、本格開発の前に小規模な検証を行い、技術的な実現可能性や効果を見極める工程を指す語はどれか。', '["PoC（概念実証）", "MLOps", "アノテーション", "デプロイ"]', '{"asked": "本開発の前に小さく試して実現性と効果を見極める工程は？", "point": "本開発の前に小さく試し、実現性と効果を見極める工程なら、PoC。", "kid": "いきなり作り込まず、まず小さく試して『本当にできそうか』を確かめる段階。", "eg": "新メニューをいきなり全店導入せず、1店舗で試して反応を見るような段階。", "terms": [["PoC（概念実証）", "本格開発の前に小規模に実現性・効果を検証する工程"], ["MLOps", "開発から運用・監視・再学習まで継続的に回す実践"]], "think": "カギは『本開発の前に小さく試して見極める』ならPoC。運用しながらずっと回す仕組みはMLOpsで段階が違う。", "vs": "MLOpsは運用まで継続的に回す実践、アノテーションは正解ラベル付け、デプロイは本番投入。事前の小規模検証がPoC。", "usecase": "効果や実現性が不確かなAI案件で、投資判断の前に行う。うまくいけば本開発へ進む。", "opt": ["正解。本開発前に小規模で実現性・効果を検証する工程。", "運用まで継続的に回す実践で、事前検証ではない。", "正解ラベルを付ける作業で、検証工程ではない。", "本番へ投入する作業で、事前検証ではない。"]}'),
  ('g-kentei-e-q38', '7. AIの社会実装に向けて', '教師あり学習に用いるデータへ、正解ラベルや境界などの情報を人手で付与していく作業を指す語はどれか。', '["アノテーション", "データクレンジング", "正則化", "デプロイ"]', '{"asked": "データに正解ラベルを人手で付ける作業は？", "point": "データに正解ラベルを人手で付ける作業なら、アノテーション。", "kid": "写真に『これは猫』と正解の札を付けるような、人手のラベル付け作業。", "eg": "問題集に模範解答を書き込む作業。これがあって初めて教師あり学習ができる。", "terms": [["アノテーション", "データに正解ラベルや境界などを人手で付与する作業"], ["データクレンジング", "欠損や誤り・重複を整えて使える状態にする作業"]], "think": "カギは『人手で正解を付ける』ならアノテーション。教師あり学習の前提となる下ごしらえ、と押さえる。", "vs": "データクレンジングは欠損や誤りを整える作業、正則化は過学習対策、デプロイは本番投入。正解ラベルを付けるのはアノテーション。", "usecase": "教師あり学習の品質を左右する。量が多いとクラウドソーシングで分担することもある。", "opt": ["正解。データに正解ラベルを人手で付ける作業。", "欠損や誤りを整える作業で、ラベル付けではない。", "過学習対策で、ラベル付けの作業ではない。", "本番へ投入する作業で、ラベル付けではない。"]}'),
  ('g-kentei-e-q39', '7. AIの社会実装に向けて', '機械学習モデルの開発・デプロイ・監視・再学習までを継続的に回し、開発と運用を密に連携させる実践を指す語はどれか。', '["MLOps", "PoC", "アノテーション", "クラウドソーシング"]', '{"asked": "開発から運用・監視・再学習まで継続的に回す実践は？", "point": "開発から運用・監視・作り直しまでを継続的に回す実践なら、MLOps。", "kid": "作って終わりにせず、動かしながら監視し、精度が落ちたら学習し直す、を回し続ける仕組み。", "eg": "店を開けたら終わりでなく、売上を見て仕入れや配置を回し続ける運営に近い。", "terms": [["MLOps", "開発・デプロイ・監視・再学習を継続的に回し、開発と運用を連携させる実践"], ["コンセプトドリフト", "運用中に傾向が変わり、モデルの精度が徐々に落ちる現象"]], "think": "カギは『運用しながら継続的に回す・開発と運用の連携』ならMLOps。事前に小さく試すPoCとは段階が違う。", "vs": "PoCは事前の小規模検証、アノテーションはラベル付け、クラウドソーシングは作業を大勢に分担する仕組み。継続運用の実践がMLOps。", "usecase": "本番で精度が落ちる（コンセプトドリフト）のを監視し、再学習で保つ。継続的な価値提供に必須。", "opt": ["正解。開発から運用・監視・再学習まで継続的に回す実践。", "事前の小規模検証で、継続運用ではない。", "ラベル付けの作業で、運用の実践ではない。", "作業を大勢に分担する仕組みで、運用の実践ではない。"]}'),
  ('g-kentei-e-q40', '8. AIに必要な数理・統計知識', 'がん検診で「本当は陽性なのに陰性と判定する見落とし」を極力避けたい場合、特に高めることが重視される指標はどれか。', '["再現率", "適合率", "正解率", "特異度"]', '{"asked": "見落とし（見逃し）を減らしたいとき重視すべき指標は？", "point": "見落とし（見逃し）を何より減らしたいなら、再現率を高める。", "kid": "本当に陽性の人を取りこぼさない割合。見逃しを減らしたい検査で重視する。", "eg": "空港の手荷物検査。多少の誤検知は許しても、危険物の見逃しは絶対に避けたい。", "terms": [["再現率", "実際に陽性のうち、正しく陽性と当てた割合。見逃しの少なさ"], ["適合率", "陽性と判定したうち、実際に陽性だった割合。誤検知の少なさ"]], "think": "見分けるカギは『何を恐れるか』。見落とし（見逃し）を減らしたい＝再現率。誤検知（空振り）を減らしたい＝適合率。", "vs": "適合率は誤検知の少なさ、正解率は全体の当たり具合（偏りに弱い）、特異度は陰性を正しく陰性と当てる割合。見逃しを減らすのは再現率。", "usecase": "病気の見逃しが致命的な医療検診や、不正の検知など『取りこぼしたくない』場面で重視する。", "opt": ["正解。見逃しを減らしたいときに重視する指標。", "誤検知の少なさを表す指標で、見逃し対策ではない。", "全体の当たり具合で、偏ったデータでは当てにならない。", "陰性を正しく当てる割合で、見逃し対策の主役ではない。"]}'),
  ('g-kentei-e-q41', '8. AIに必要な数理・統計知識', '適合率と再現率は一方を高めると他方が犠牲になりやすい。両者のバランスを1つの数値で捉えるためによく使われる指標はどれか。', '["F値", "正解率", "AUC", "決定係数"]', '{"asked": "適合率と再現率のバランスを1つの数値で見る指標は？", "point": "適合率と再現率のバランスを、1つの数値で見るなら、F値。", "kid": "見逃しの少なさと誤検知の少なさ、両方をまとめて1つの点数で表す指標。", "eg": "守りと攻めの両方のバランスを、1つの総合評価点にまとめるイメージ。", "terms": [["F値", "適合率と再現率の調和平均。両者のバランスを1数値で表す"], ["正解率", "全体の当たり具合。データが偏ると当てにならない"]], "think": "カギは『適合率と再現率のバランスを1つの数値で』ならF値。全体の正解率は、データが偏ると当てにならない。", "vs": "正解率は偏りに弱い全体の当たり具合、AUCは閾値によらない総合力、決定係数は回帰の当てはまり。両者の調和がF値。", "usecase": "陽性が少ない偏ったデータで、正解率が当てにならないときの評価に使う。", "opt": ["正解。適合率と再現率のバランスを1数値で表す指標。", "全体の当たり具合で、偏ったデータに弱い。", "閾値によらない総合力の指標で、両者の調和ではない。", "回帰の当てはまりを表す指標で、分類の指標ではない。"]}'),
  ('g-kentei-e-q42', '8. AIに必要な数理・統計知識', '正規分布に従うデータで、平均から標準偏差±1の範囲におよそ何割のデータが含まれるか。最も近いものはどれか。', '["約68%", "約50%", "約95%", "約99.7%"]', '{"asked": "平均から標準偏差±1の範囲に入るデータの割合は？", "point": "標準偏差1つ分（±1σ）はおよそ68%。2つ分で約95%、3つ分で約99.7%。", "kid": "平均のまわり標準偏差1つ分の幅に、だいたい7割弱のデータが集まる。", "eg": "テストの点が正規分布なら、平均±1σの間に受験者の約7割が収まるイメージ。", "terms": [["標準偏差", "データが平均のまわりにどれだけ散らばっているかの大きさ"], ["正規分布", "平均を中心に左右対称の釣鐘型に分布する代表的な分布"]], "think": "覚え方は『68-95-99.7』。標準偏差1つ分で約68%、2つ分で約95%、3つ分で約99.7%。ここでは1つ分を聞かれている。", "vs": "約50%は中央値までの範囲の感覚、約95%は±2σ、約99.7%は±3σ。±1σは約68%。", "usecase": "外れ値の判断や品質管理（何σ外れたら異常とみなすか）の基準として使う。", "opt": ["正解。±1σにはおよそ68%が含まれる。", "±1σの割合ではない。中央値近辺の感覚と混同。", "±2σの割合で、1つ分ではない。", "±3σの割合で、1つ分ではない。"]}'),
  ('g-kentei-e-q43', '8. AIに必要な数理・統計知識', '「アイスの売上が増えると水難事故も増える」というデータの関係について、最も適切な解釈はどれか。', '["共通の原因（気温）が両方を押し上げている可能性がある", "アイスの売上が水難事故の直接の原因である", "水難事故の増加がアイスの売上を押し上げている直接の原因だ", "両者に相関はなく、まったくの偶然にすぎない"]', '{"asked": "一緒に増える2つのデータの関係、正しい解釈は？", "point": "『一緒に動く』だけでは因果とは言えない。隠れた共通の原因がないか疑う。", "kid": "2つが同時に増えても、片方がもう片方の原因とは限らない。裏に共通の原因があることが多い。", "eg": "夏は暑いのでアイスも売れ、泳ぐ人も増えて事故も増える。犯人は『気温』という共通の原因。", "terms": [["相関", "2つの量が一緒に動く関係。強くても因果とは限らない"], ["因果", "一方が他方の原因になっている関係"]], "think": "カギは『相関≠因果』。一緒に動くだけでは、どちらかが原因とは言えない。隠れた共通の原因（この例では気温）を疑うのが正しい姿勢。", "vs": "アイスが事故の原因、事故がアイスの原因、という直接の因果は不自然。相関が無い（偶然）とも言えない。共通原因を疑うのが妥当。", "usecase": "データ分析で相関を見つけても、施策の根拠にする前に因果かどうかを検証する姿勢が要る。", "opt": ["正解。共通の原因が両方を押し上げている可能性を疑うべき。", "アイスが事故を起こすという直接の因果は不自然。", "事故がアイスを売るという直接の因果は不自然。", "実際に一緒に動いており、無関係とは言えない。"]}'),
  ('g-kentei-e-q44', '9. AIに関する法律と契約', '日本の著作権法第30条の4が、一定の条件下で著作物を機械学習の訓練データとして利用できるとする考え方として、最も適切なものはどれか。', '["鑑賞・享受を目的としない解析での利用は、原則として許諾なく行える", "学習目的であっても、常に権利者一人ひとりから許諾を得る必要がある", "営利目的でなければ、どんな利用も無制限に許されるとされる", "一度公開された著作物は、すべて自由に利用してよいとされる"]', '{"asked": "著作権法30条の4の、機械学習利用に関する考え方は？", "point": "作品を『味わう』目的でなく、学習の材料として使う解析利用なら、原則許諾なくOK。", "kid": "人が楽しむためでなく、AIの学習のために解析する利用は、原則として許可なく行える。", "eg": "小説を『読んで楽しむ』のはNG方向だが、文章の統計を取って学習させる解析はOK方向。", "terms": [["著作権法30条の4", "鑑賞・享受を目的としない解析利用を、原則許諾なく認める規定"], ["享受", "作品を鑑賞して知的・精神的に楽しむこと"]], "think": "判断のカギは『味わう目的か、そうでないか』。学習のための解析は“味わう目的でない”ので原則OK。ただし権利者の利益を不当に害する場合は除く。", "vs": "常に許諾が必要、営利でなければ無制限、公開物はすべて自由、はいずれも言い過ぎ。鑑賞目的でない解析利用が原則OK、が正しい。", "usecase": "生成AIの学習データ利用の可否を考えるときの基本の考え方。ただし例外規定に注意。", "opt": ["正解。鑑賞・享受目的でない解析利用は原則許諾不要。", "常に許諾が必要というのは誤りで、原則不要の場合がある。", "営利でなければ無制限、というのは言い過ぎ。", "公開物をすべて自由に使える、というのは誤り。"]}'),
  ('g-kentei-e-q45', '9. AIに関する法律と契約', '企業が秘密として管理し、事業に有用で、公然と知られていない技術情報などを保護する、不正競争防止法上の枠組みはどれか。', '["営業秘密", "特許権", "著作権", "意匠権"]', '{"asked": "秘密管理・有用・非公知の情報を守る不正競争防止法上の枠組みは？", "point": "『秘密管理・有用・非公知』の3つを満たす情報を守るのが、営業秘密。", "kid": "社内で秘密に管理していて、役立ち、まだ知られていない情報を守る仕組み。", "eg": "門外不出のレシピを、公開せず秘密のまま守る発想。特許のように公開はしない。", "terms": [["営業秘密", "秘密管理・有用性・非公知の3要件を満たす情報を守る不正競争防止法上の枠組み"], ["特許権", "発明を公開する代わりに一定期間独占できる権利"]], "think": "カギは『秘密管理・役立つ・知られていない』の3点セットなら営業秘密。公開して独占権をもらう特許とは逆の発想（隠して守る）。", "vs": "特許権は公開して独占権をもらう、著作権は表現を保護、意匠権はデザインを保護。秘密のまま守るのが営業秘密。", "usecase": "製法やアルゴリズムなど、公開したくない技術情報の保護に使う。管理体制が要件を満たすことが重要。", "opt": ["正解。秘密管理・有用・非公知の情報を守る枠組み。", "発明を公開して独占する権利で、秘密のまま守るのとは逆。", "表現を保護する権利で、秘密情報の保護ではない。", "デザインを保護する権利で、技術情報の秘密保護ではない。"]}'),
  ('g-kentei-e-q46', '9. AIに関する法律と契約', '完成物を最初に約束しにくいAI開発の特性をふまえ、アセスメント・PoC・開発・追加学習といった段階に分けて契約を進める考え方はどれか。', '["探索的段階型の開発契約", "一括請負契約", "労働者派遣契約", "保守契約"]', '{"asked": "AIの不確実性をふまえ、段階に分けて進める契約の考え方は？", "point": "最初に完成を約束せず、段階に分けて進めるなら、探索的段階型。", "kid": "AIは作ってみないと結果が読めないので、段階ごとに区切って契約を進める考え方。", "eg": "手探りの研究開発を、いきなり成果を約束させず、フェーズごとに見直しながら進める。", "terms": [["探索的段階型の開発契約", "AIの不確実性をふまえ、段階に分けて進める契約の考え方"], ["一括請負契約", "成果物の完成を固く約束する契約"]], "think": "カギは『最初に完成を約束せず、段階に分けて進める』なら探索的段階型。成果を固く約束する一括請負とは、AIの不確実性への向き合い方が逆。", "vs": "一括請負は完成を約束、派遣契約は労働力の提供、保守契約は運用後の維持。不確実性に段階対応するのが探索的段階型。", "usecase": "経産省のモデル契約などで示される、AI開発の実務的な進め方。発注者・受注者のリスク分担に使う。", "opt": ["正解。段階に分けて不確実性に対応する契約の考え方。", "完成を固く約束する契約で、AIの不確実性と相性が悪い。", "労働力を提供する契約で、開発成果の契約ではない。", "運用後の維持の契約で、開発段階の進め方ではない。"]}'),
  ('g-kentei-e-q47', '10. AI倫理・AIガバナンス', '入力データに人には気づきにくい微小な変化を加えることで、AIモデルにわざと誤った判断をさせる攻撃を指す語はどれか。', '["敵対的サンプル", "データポイズニング", "プロンプトインジェクション", "ハルシネーション"]', '{"asked": "推論時の入力に小さなノイズを混ぜてAIを誤らせる攻撃は？", "point": "使うときの入力に、人には気づけない小さなノイズを混ぜて誤らせるなら、敵対的サンプル。", "kid": "人の目には同じに見える画像に微妙なノイズを足して、AIだけを誤判定させる攻撃。", "eg": "標識にわずかな細工をして、人には普通に見えるのに自動運転AIだけ読み間違えさせる。", "terms": [["敵対的サンプル", "推論時の入力に微小な変化を加え、AIを誤判定させる攻撃"], ["データポイズニング", "学習データに悪意ある例を混ぜ、学習の段階からモデルを狂わせる攻撃"]], "think": "カギは『使うとき（推論時）の入力に小さな変化を混ぜて誤らせる』なら敵対的サンプル。学習データを汚すポイズニングとは狙う段階が違う。", "vs": "データポイズニングは学習の段階を狙う、プロンプトインジェクションは指示文に細工してLLMを操る、ハルシネーションは生成AIの出力の誤り。推論時の入力細工は敵対的サンプル。", "usecase": "画像認識や自動運転の安全性評価で重要。防御には敵対的学習や入力の検査を用いる。", "opt": ["正解。推論時の入力に微小な変化を加えて誤らせる攻撃。", "学習データを汚す攻撃で、狙う段階が違う。", "指示文に細工してLLMを操る攻撃で、別物。", "生成AIの出力の誤りで、攻撃ではない。"]}'),
  ('g-kentei-e-q48', '10. AI倫理・AIガバナンス', 'AIの判断根拠を人間が理解できる形で説明しようとする「説明可能なAI（XAI）」の代表的な手法はどれか。', '["LIMEやSHAP", "SGDやAdam", "ResNetやVGG", "BERTやGPT"]', '{"asked": "AIの判断根拠を説明する『説明可能なAI』の代表手法は？", "point": "『なぜその判断か』を、効いた特徴で説明する手法なら、LIMEやSHAP。", "kid": "AIがなぜそう判断したかを、どの特徴が効いたかで人に説明する手法。", "eg": "融資を断ったAIに『なぜ？』と聞くと『年収と勤続年数が主因』と根拠を示すイメージ。", "terms": [["XAI", "AIの判断根拠を人が理解できる形で示す取り組み"], ["LIME/SHAP", "どの特徴が判断にどれだけ効いたかを説明する代表的手法"]], "think": "カギは『なぜその判断か』を説明する手法ならLIMEやSHAP。最適化手法やモデルの名前とは役割の層が違う。", "vs": "SGDやAdamは最適化手法、ResNetやVGGは画像認識モデル、BERTやGPTは言語モデル。判断根拠を説明するのはLIMEやSHAP。", "usecase": "融資・医療など判断の説明責任が問われる分野で、モデルの根拠提示に使う。", "opt": ["正解。判断に効いた特徴で根拠を説明する代表手法。", "最適化手法で、判断根拠の説明ではない。", "画像認識モデルで、説明手法ではない。", "言語モデルで、説明手法ではない。"]}'),
  ('g-kentei-e-q49', '10. AI倫理・AIガバナンス', '生成AIが、事実に反する内容を、あたかも正しいかのようにもっともらしく出力してしまう現象を指す語はどれか。', '["ハルシネーション", "ディープフェイク", "フィルターバブル", "敵対的サンプル"]', '{"asked": "生成AIが事実でないことをもっともらしく出力する現象は？", "point": "事実でないことをもっともらしく出力するなら、ハルシネーション。", "kid": "生成AIが、もっともらしい口調で、実際には間違った内容を言ってしまう現象。", "eg": "実在しない論文や出来事を、さも本当のように自信たっぷりに説明してしまう。", "terms": [["ハルシネーション", "生成AIが事実に反する内容をもっともらしく出力する現象"], ["ディープフェイク", "実在人物の偽動画・偽音声を作る合成技術"]], "think": "カギは『事実に反する出力をもっともらしく』ならハルシネーション。偽の映像を作るディープフェイクとは、起きる場面が違う（こちらは生成AIの出力の誤り）。", "vs": "ディープフェイクは偽動画の生成、フィルターバブルは情報の偏り、敵対的サンプルは入力を細工する攻撃。出力の事実誤りはハルシネーション。", "usecase": "生成AIを業務利用するとき、出力の事実確認（ファクトチェック）が必須である理由になる。", "opt": ["正解。事実に反する内容をもっともらしく出力する現象。", "偽動画・偽音声を作る技術で、出力の事実誤りではない。", "情報の偏りの現象で、出力の誤りではない。", "入力を細工する攻撃で、出力の誤りではない。"]}'),
  ('g-kentei-e-q50', '10. AI倫理・AIガバナンス', 'レコメンドなどのアルゴリズムによって、利用者が自分の関心に合う情報にばかり囲まれ、視野が狭まっていく状態を指す語はどれか。', '["フィルターバブル", "エコーチェンバー", "ハルシネーション", "デジタルデバイド"]', '{"asked": "おすすめが好みの情報ばかり見せ、視野が狭まる状態は？", "point": "おすすめが好みの情報ばかり見せ、視野が狭まる状態なら、フィルターバブル。", "kid": "アルゴリズムが好みに合う情報だけを見せ続け、泡の中のように視野が狭まる状態。", "eg": "SNSのおすすめが好みの投稿ばかりになり、他の見方に触れなくなっていくイメージ。", "terms": [["フィルターバブル", "おすすめの仕組みで好みの情報に囲まれ視野が狭まる状態"], ["エコーチェンバー", "同じ意見の人どうしで反響し合い、その意見が増幅される現象"]], "think": "カギは『おすすめが好みの情報で囲い込む』ならフィルターバブル。原因が『おすすめの仕組み』か『人のつながり』かで、エコーチェンバーと区別すると分かりやすい。", "vs": "エコーチェンバーは同じ意見どうしの反響で増幅、ハルシネーションは出力の事実誤り、デジタルデバイドは情報格差。おすすめによる情報の偏りがフィルターバブル。", "usecase": "レコメンドの副作用として、意見の多様性が失われるリスクの議論で使う。", "opt": ["正解。おすすめの仕組みで好みの情報に囲まれ視野が狭まる状態。", "同じ意見どうしの反響で増幅する現象で、原因が人のつながり。", "出力の事実誤りで、情報の偏りではない。", "情報格差のことで、情報の偏りとは別。"]}')
) AS v(source_ref, category_name, question_text, options, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei-e'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
